 "versusx": {
  "file": "src/anticheat/analyze.js",
  "lang": "js",
  "caption": "How the platform spots engine-assisted play. Every move is replayed through the game's own AI to see how close it was to the best move, and the player's thinking time is checked for robot-like steadiness. One strong signal isn't enough: results are judged across many games.",
  "src": "// Post-game cheat signals for one Draft match. A single game proves little:\n// reports are stored per match and judged across many games (see flags.js).\nimport { newGame, legalMoves, applyMove } from '../games/draft/rules.js';\nimport { judgeMove } from '../games/draft/engine.js';\n\nconst OPENING_PLIES = 6; // everyone plays book-like openings; skip them\nconst DEPTH = 5;\n\nconst cv = (xs) => {\n  if (xs.length < 5) return null;\n  const mean = xs.reduce((a, b) => a + b, 0) / xs.length;\n  const sd = Math.sqrt(xs.reduce((a, b) => a + (b - mean) ** 2, 0) / xs.length);\n  return mean ? sd / mean : null;\n};\n\n// moves: [{ from, to, captures }], times: think time per ply in ms, blurs: { w, b }\nexport function analyzeGame(moves, times, blurs = {}) {\n  let s = newGame();\n  const per = { w: { judged: 0, best: 0, loss: 0, thinks: [] }, b: { judged: 0, best: 0, loss: 0, thinks: [] } };\n  moves.forEach((mv, i) => {\n    const side = s.turn, p = per[side];\n    // forced moves (one choice, often a mandatory capture) say nothing about the player\n    if (legalMoves(s).length > 1) {\n      if (i >= OPENING_PLIES) {\n        const j = judgeMove(s, mv, DEPTH);\n        p.judged++;\n        if (j.best) p.best++;\n        p.loss += Math.min(j.loss ?? 300, 300);\n      }\n      if (i >= 2 && times[i] != null) p.thinks.push(times[i]);\n    }\n    s = applyMove(s, mv);\n  });\n\n  const out = {};\n  for (const side of ['w', 'b']) {\n    const p = per[side];\n    const bestRate = p.judged ? p.best / p.judged : null;\n    const avgLoss = p.judged ? p.loss / p.judged : null;\n    const timeCv = cv(p.thinks);\n    out[side] = {\n      judged: p.judged, bestRate, avgLoss, timeCv, blurs: blurs[side] || 0,\n      // engine-like accuracy over enough real decisions, or near-perfect play with steady clockwork timing\n      suspicious: p.judged >= 12 && ((bestRate >= 0.9 && avgLoss <= 10) || (bestRate >= 0.8 && timeCv != null && timeCv < 0.3)),\n    };\n  }\n  return out;\n}"
 },
 "finlo": {
  "file": "src/core/forecast.ts",
  "lang": "ts",
  "caption": "Forecasting built for short, noisy personal-finance history. The function learns how strongly to react to each new month, then projects the trend forward. Nearby code backtests every forecast so a shaky prediction is labelled shaky.",
  "src": "/**\n * Holt's linear trend method.\n *\n * `alpha` smooths the level, `beta` the trend. Both are fitted by grid search\n * rather than hardcoded, because the right smoothing for someone with steady\n * salaried income is very different from the right smoothing for someone whose\n * income arrives in irregular lumps.\n */\nexport function holtLinear(\n  values: number[],\n  horizon: number,\n  alpha: number,\n  beta: number\n): number[] {\n  if (values.length === 0) return new Array(horizon).fill(0);\n  if (values.length === 1) return new Array(horizon).fill(values[0]);\n\n  let level = values[0];\n  let trend = values[1] - values[0];\n\n  for (let i = 1; i < values.length; i++) {\n    const prevLevel = level;\n    level = alpha * values[i] + (1 - alpha) * (level + trend);\n    trend = beta * (level - prevLevel) + (1 - beta) * trend;\n  }\n\n  const out: number[] = [];\n  for (let h = 1; h <= horizon; h++) {\n    out.push(level + h * trend);\n  }\n  return out;\n}"
 },
