  "src": "import { useCallback } from 'react';\nimport { Alert, Linking } from 'react-native';\nimport { useCodeDialStore } from '../store/useCodeDialStore';\nimport type { UssdAction } from '../types/ussd';\nimport { dialUssdCode, shouldPromptForSpend } from '../utils/dialer';\nimport { suggestedSpendCategory } from '../utils/categories';\n\nexport function useDialAction() {\n  const setPendingPurchase = useCodeDialStore(state => state.setPendingPurchase);\n  const clearPendingPurchase = useCodeDialStore(state => state.clearPendingPurchase);\n  const logRecentAction = useCodeDialStore(state => state.logRecentAction);\n\n  return useCallback(async (action: UssdAction) => {\n    if (action.network !== 'Bank' && shouldPromptForSpend(action.serviceType)) {\n      setPendingPurchase({\n        actionId: action.id,\n        title: action.title,\n        network: action.network,\n        category: suggestedSpendCategory(action)\n      });\n    }\n\n    try {\n      await Linking.openURL(dialUssdCode(action.code));\n      logRecentAction(action.id);\n    } catch {\n      clearPendingPurchase();\n      Alert.alert(\n        'Unable to open the dialer',\n        'Check that this device supports phone dialler links and try again.'\n      );\n    }\n  }, [clearPendingPurchase, logRecentAction, setPendingPurchase]);\n}"
