 "hoodwatch": {
  "file": "src/guard.js",
  "lang": "js",
  "caption": "The safety verdict shown on every token card. It combines a simulated buy-and-sell test, contract red flags and how concentrated the holders are into one plain answer: safe, caution or danger, with the reasons.",
  "src": "export function assess({ gp, info, holders, sellTest }) {\n  const danger = [];\n  const caution = [];\n\n  const tx = taxes(sellTest);\n  if (sellTest && !sellTest.sellable) danger.push('Honeypot: selling fails');\n  else if (tx) {\n    const worst = Math.max(tx.buy, tx.sell);\n    if (worst >= 30) danger.push(`Tax ${Math.round(worst)}%`);\n    else if (worst >= 10) caution.push(`Tax ${Math.round(worst)}%`);\n  }\n\n  if (gp) {\n    if (!sellTest && (yes(gp.is_honeypot) || yes(gp.cannot_sell_all))) danger.push('You may not be able to sell');\n    if (!sellTest && yes(gp.cannot_buy)) danger.push('Buying is blocked');\n    if (yes(gp.hidden_owner)) danger.push('Has a hidden owner');\n    if (yes(gp.selfdestruct)) danger.push('Contract can self-destruct');\n    if (yes(gp.owner_change_balance)) danger.push('Owner can change balances');\n    if (yes(gp.can_take_back_ownership)) caution.push('Owner can take back control');\n    if (yes(gp.is_mintable)) caution.push('More tokens can be minted');\n    if (yes(gp.transfer_pausable)) caution.push('Trading can be paused');\n    if (!sellTest && yes(gp.slippage_modifiable)) caution.push('Tax can be changed');\n    if (yes(gp.is_blacklisted)) caution.push('Wallets can be blocked');\n    if (!tx) { // the contract's own tax, only when the sell test couldn't run\n      const worst = Math.max(taxPct(gp.buy_tax) || 0, taxPct(gp.sell_tax) || 0);\n      if (worst >= 30) danger.push(`Tax ${Math.round(worst)}%`);\n      else if (worst >= 10) caution.push(`Tax ${Math.round(worst)}%`);\n    }\n  }\n\n  const onLaunchpad = info.launchpad && !info.launchpad.graduated;\n  if (info.liquidity != null && info.liquidity < 3000 && !onLaunchpad) caution.push('Very little liquidity');\n\n  const top10 = topWalletsShare(gp, holders, info.pool);\n  if (top10 != null && (info.holders ?? 0) >= MIN_HOLDERS_FOR_SPREAD && top10 >= 50) caution.push(`Top 10 wallets hold ${Math.round(top10)}%`);\n  if (info.holders != null && info.holders < MIN_HOLDERS_FOR_SPREAD) caution.push(`Very new: only ${info.holders} holders`);\n\n  const checked = Boolean(gp || sellTest);\n  const level = danger.length ? 'danger' : caution.length ? 'caution' : checked ? 'safe' : 'unknown';\n  return { level, notes: [...danger, ...caution], top10 };\n}"
 },
 "prowl": {
  "file": "api/_lib/guard.js",
  "lang": "js",
  "caption": "A weighted risk score with a safety rule: one critical red flag, like a honeypot, caps the score no matter how good everything else looks. Checks that couldn't be verified are never counted as passes.",
  "src": "export function score(checks) {\n  const credit = { pass: 1, warn: 0.5, fail: 0 };\n  let earned = 0;\n  let possible = 0;\n  let unknownWeight = 0;\n  for (const c of checks) {\n    const w = SEVERITY_WEIGHT[c.severity];\n    if (c.status === 'unknown') {\n      unknownWeight += w;\n      continue;\n    }\n    earned += w * credit[c.status];\n    possible += w;\n  }\n  let pctScore = possible ? Math.round((earned / possible) * 100) : 0;\n\n  // One critical failure (honeypot, no sells, unlocked LP, freeze, huge tax)\n  // is enough to make a token dangerous, whatever else looks fine.\n  const criticalFails = checks.filter((c) => c.severity === 'critical' && c.status === 'fail');\n  const highFails = checks.filter((c) => c.severity === 'high' && c.status === 'fail');\n  // A critical check we couldn't verify (e.g. LP lock on some pool types)\n  // means we can't call the token low-risk.\n  const criticalUnknown = checks.filter((c) => c.severity === 'critical' && c.status === 'unknown');\n  if (criticalFails.length) pctScore = Math.min(pctScore, 25);\n  else if (highFails.length >= 2) pctScore = Math.min(pctScore, 50);\n  else if (criticalUnknown.length) pctScore = Math.min(pctScore, 79);"
 },
 "deliver": {
  "file": "contracts/DeliverEscrow.sol",
  "lang": "sol",
  "caption": "The rules enforced on the blockchain so nobody has to be trusted. An agent must put up a stake to accept a task. If the work passes, the agent is paid; if it fails, the stake is slashed and the requester is refunded.",
  "src": "function acceptTask(uint256 id) external payable nonReentrant {\n    Task storage t = tasks[id];\n    require(t.status == Status.Open, \"not open\");\n    require(t.agent == address(0), \"already taken\");\n    require(msg.sender != t.requester, \"requester cannot accept\");\n    require(msg.value == t.stake, \"incorrect stake\");\n\n    t.agent = msg.sender;\n    t.status = Status.Accepted;\n    emit TaskAccepted(id, msg.sender, msg.value);\n}\n\n// …\n\nfunction _settle(uint256 id, bool success) internal {\n    Task storage t = tasks[id];\n\n    if (success) {\n        uint256 fee = (t.reward * platformFeeBps) / 10000;\n        uint256 agentPayout = t.reward - fee + t.stake;\n        completed[t.agent] += 1;\n        t.status = Status.Verified;\n        t.settledAt = block.timestamp;\n        _transfer(t.agent, agentPayout);\n        if (fee > 0) _transfer(owner(), fee);\n        emit TaskSettled(id, Status.Verified, agentPayout, 0);\n    } else {\n        slashed[t.agent] += 1;\n        t.status = Status.Failed;\n        t.settledAt = block.timestamp;\n        _transfer(t.requester, t.stake); // slash stake to requester\n        _transfer(t.requester, t.reward); // refund escrow\n        emit TaskSettled(id, Status.Failed, 0, t.reward + t.stake);\n    }\n}"
 },
