  "src": "# ── Weight by measured skill ABOVE CHANCE ──────────────────────────\n# 3 classes, so 1/3 is the no-skill baseline. A model at or below it\n# contributes nothing rather than diluting the ones that work.\nself.val_accuracy = acc\nedge = {k: max(0.0, v - 1.0 / 3.0) for k, v in acc.items()}\ntotal = sum(edge.values())\n\nif total > 0:\n    self.model_weights = {k: v / total for k, v in edge.items()}\nelse:\n    logger.warning(\"No model beat chance on validation — falling back \"\n                   \"to configured weights\")\n    self.model_weights = dict(config.ENSEMBLE_WEIGHTS)"
